'use strict';
(()=>{
const $=id=>document.getElementById(id), World=window.ValdaraWorld, CD=window.CenizasCharacterData, SAVE='cenizas-valdara-v1';
const stick=window.createJoystick($('joystick'),$('joystick-knob'));
let scene=null,character=null,toastTimer=null,stage=0,position={...World.start};
try{const v=JSON.parse(localStorage.getItem(SAVE));if(v&&Number.isInteger(v.stage)&&v.stage>=0&&v.stage<=3)stage=v.stage;if(v&&Number.isFinite(v.x)&&Number.isFinite(v.y)&&World.walkable(v.x,v.y))position={x:v.x,y:v.y}}catch{}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3300)}
function save(){if(scene?.hero)position={x:scene.hero.x,y:scene.hero.y};try{localStorage.setItem(SAVE,JSON.stringify({...position,stage}));$('save-state').textContent='Progreso guardado en este dispositivo';}catch{$('save-state').textContent='No se pudo guardar el progreso en este navegador'}}
function refreshCharacter(){try{const v=JSON.parse(localStorage.getItem('cenizas-character-v1'));character=v&&CD.classes[v.class]&&CD.raceData[v.race]&&Array.isArray(v.base)&&v.base.length===6&&v.base.every(n=>Number.isFinite(n)&&n>=8&&n<=18)?v:null}catch{character=null}const name=character?.name?.trim()||'Viajero';$('player-name').textContent=name;$('player-class').textContent=character?`${character.race} · ${character.class} · ${character.subclass||'sin subclase'} · Nivel 1`:'Personaje de exploración · Nivel 1';if(character){const con=character.base[2]+(CD.raceData[character.race]?.mods[2]||0),hp=Math.max(1,(CD.classes[character.class]?.hp||6)+Math.floor((con-10)/2))+(character.feats?.includes('Dureza')?3:0)+(character.class==='Mago'?3:0);$('player-hp').textContent=`${hp} / ${hp} PG`}else $('player-hp').textContent='Nivel 1';if(scene?.nameTag)scene.nameTag.setText(name);if(scene?.hero)syncHeroDesign(scene)}
function characterReadyBridge(candidate=character){return typeof candidate?.name==='string'&&candidate.name.trim().length>0&&CD.raceData[candidate.race]&&CD.classes[candidate.class]&&CD.subclassData[candidate.class]?.some(entry=>entry[0]===candidate.subclass)&&CD.genderData.some(entry=>entry[0]===candidate.gender)&&Array.isArray(candidate.base)&&candidate.base.length===6&&candidate.base.every(n=>Number.isFinite(n)&&n>=8&&n<=18)}
const heroRaceDesigns={Humano:{skin:0xd9a27d,hair:0x68452e,tint:0xd9c09b,scale:1,sigil:'◇'},Elfo:{skin:0xe8c29d,hair:0x9b7655,tint:0xe6d8bd,scale:1,ears:'point',sigil:'✧'},Enano:{skin:0xc68d62,hair:0x493328,tint:0xb99d7d,scale:.9,beard:true,sigil:'⬟'},Orco:{skin:0x819853,hair:0x283329,tint:0x7f945a,scale:1.08,ears:'point',tusks:true,sigil:'◆'},Mediano:{skin:0xd4a177,hair:0x5d3c28,tint:0xc9b58b,scale:.78,sigil:'•'},Gnomo:{skin:0xd0a17f,hair:0x734934,tint:0xbfa3b1,scale:.82,ears:'point',sigil:'✿'},Semielfo:{skin:0xe1b68f,hair:0x5a3c2c,tint:0xd7c5ad,scale:1,ears:'point',sigil:'◈'},Semiorco:{skin:0xa08562,hair:0x293329,tint:0x9b936e,scale:1.04,ears:'point',tusks:true,sigil:'✹'}};
function drawHeroDesign(target,c){if(!target?.hero)return;const race=heroRaceDesigns[c?.race]||heroRaceDesigns.Humano,scale=race.scale||1;target.hero.clearTint?.();target.hero.setDisplaySize(92*scale,92*scale);if(target.heroVisual)target.heroVisual.clear().setPosition(target.hero.x,target.hero.y).setDepth(target.hero.y-.2);if(target.heroBadge)target.heroBadge.setVisible(false)}
function syncHeroDesign(target=scene){if(!target?.hero)return;drawHeroDesign(target,character||{race:'Humano',class:'Guerrero',subclass:'Guardia',gender:'No binario'});}
function modalOpen(){return !!document.querySelector('dialog[open]')||document.getElementById('main-menu')?.dataset.active==='true'||(document.getElementById('intro-cinema')&&!document.getElementById('intro-cinema').hidden)}
function openModal(id){scene?.stop();if(id==='journal-modal')journal();if(id==='sheet-modal'){if($('sheet-frame').getAttribute('src')==='about:blank')$('sheet-frame').src='character.html';}$(id).showModal();if(id==='region-modal')window.RegionMap.open()}
function journal(){const tasks=[['Hablar con Elara',stage>=1],['Mostrar la carta y obtener permiso',stage>=2],['Acercarse a la puerta de Valdara',stage>=3]];$('objectives').replaceChildren(...tasks.map(([text,done])=>{const li=document.createElement('li');li.textContent=(done?'✓ ':'○ ')+text;li.className=done?'done':'';return li}));$('journal-note').textContent=stage>=2?'Elara reconoció el sello: su hermano recibió una carta igual antes de desaparecer. Buscarás respuestas al otro lado de la puerta.':'La guardia del puente parece reconocer a quienes llegan con una carta como la tuya.'}
function nearEntrance(){const p=scene?.hero||position;return stage>=2&&Math.hypot(p.x-World.gate.x,p.y-World.gate.y)<=65}
function entranceButton(){$('continue-adventure').hidden=!nearEntrance()}
function quest(){const done=stage>=3,permission=stage>=2;entranceButton();$('quest-title').textContent=done?'Un nombre en la puerta':permission?'El paso a Valdara':'La carta sellada';$('quest-text').textContent=done?'Escena completada':permission?'Ve a la puerta de Valdara':'Habla con Elara';$('quest-go').textContent='›';$('quest-go').setAttribute('aria-label','Abrir mapa regional y ver tu ubicación');}
function dialogue(node=0){scene?.stop();const name=character?.name?.trim()||'viajero';const nodes={0:{text:`Alto, ${name}. Las puertas cierran al caer la noche. No pareces un mercader… ¿Qué te trae a Valdara?`,options:[['Mostrar la carta sellada',1],['¿Por qué están cerrando las puertas?',4]]},1:{text:'Ese sello… Mi hermano recibió uno igual. Partió hacia el monasterio hace seis días y no volvió. ¿La ceniza de tu carta también sigue caliente?',options:[['Sí. Dice que mi nombre está en una puerta.',2]]},2:{text:'Entonces no llegaste por casualidad. Hace trece años que las campanas no suenan, pero esta mañana oí una bajo la ciudad. Busca al campanero cuando entres. Él sabía qué estaba esperando mi hermano.',options:[['Iré a buscarlo. Déjame pasar.',3]]},3:{text:'Te daré paso. Acércate a la puerta y avisaré al centinela. Y si encuentras a Darien… dile que su hermana todavía lo espera.',options:[['Acercarme a la puerta',-2],['Antes quiero revisar mis cosas.',-1]]},4:{text:'Hay gente desapareciendo. Primero los viajeros; ahora también los nuestros. La orden dice que es por seguridad. Yo digo que tienen miedo de lo que hay dentro.',options:[['Hay algo que debes ver. Mostrar la carta.',1],['Entiendo. Volveré en un momento.',-1]]},5:{text:'El centinela está avisado. Ve a la puerta. Recuerda: busca al campanero, y pregunta por Darien.',options:[['Ir a la puerta',-2],['Seguir explorando el puente',-1]]}};
if(node===1)stage=Math.max(stage,1);if(node===3)stage=Math.max(stage,2);quest();save();const data=nodes[node];$('speech-text').textContent=data.text;$('answers').replaceChildren(...data.options.map(([label,next])=>{const b=document.createElement('button');b.textContent='› '+label;b.onclick=()=>{if(next<0){$('dialogue').close();if(next===-2)scene?.goGate()}else dialogue(next)};return b}));if(!$('dialogue').open)$('dialogue').showModal()}
class BridgeScene extends Phaser.Scene{
constructor(){super('Valdara');this.route=[];this.pending=null;this.failed=false}
preload(){this.load.on('progress',p=>$('load-progress').value=p);this.load.on('loaderror',()=>{this.failed=true;$('load-text').textContent='No pudimos cargar el paisaje. Recarga la página para volver a intentarlo.'});this.load.image('world','valdara.webp');let skin='hero-walk-v2.webp';try{const c=JSON.parse(localStorage.getItem('cenizas-character-v1'));const cls=c?.class;skin=cls==='Mago'&&c?.subclass==='Tejedor'?'identity-mage-ash-pixel.webp':cls==='Mago'?'identity-mage-pixel.webp':cls==='Pícaro'?'identity-rogue-pixel.webp':'identity-warrior-pixel.webp';const progress=JSON.parse(localStorage.getItem('cenizas-campaign-v2'));if(progress?.equipped==='vigilia'&&progress.items?.includes('Capa de la Vigilia')&&skin==='hero-walk-v2.webp')skin='hero-vigilia.webp';}catch{}this.load.image('traveler',skin);this.load.image('guard','guard.webp');this.load.image('trail-sign','trail-sign.webp')}
create(){if(this.failed)return;scene=this;this.add.image(0,0,'world').setOrigin(0).setDisplaySize(1536,1024);const texture=this.textures.get('traveler'),source=texture.getSourceImage(),columns=source.width<1400?2:4,rows=source.height<1300?2:4;this.travelerColumns=columns;this.travelerRows=rows;for(let r=0;r<rows;r++)for(let c=0;c<columns;c++){const x=Math.round(c*source.width/columns),y=Math.round(r*source.height/rows);texture.add(r*columns+c,0,x,y,Math.round((c+1)*source.width/columns)-x,Math.round((r+1)*source.height/rows)-y)}for(let r=0;r<rows;r++)this.anims.create({key:'walk'+r,frames:[0,1,2,3].slice(0,columns).map(c=>({key:'traveler',frame:r*columns+c})),frameRate:7,repeat:-1});
this.add.image(780,480,'trail-sign').setOrigin(.5,.94).setDisplaySize(104,126).setDepth(480).setInteractive({useHandCursor:true}).on('pointerdown',()=>toast('← Camino exterior · Valdara: continúa hacia la puerta →'));this.marker=this.add.ellipse(0,0,30,13,0xe6dca0,.14).setStrokeStyle(2,0xffe5a0,.9).setVisible(false).setDepth(9);this.playerShadow=this.add.ellipse(position.x,position.y,39,13,0x223e31,.3).setDepth(position.y-.1);this.hero=this.add.sprite(position.x,position.y,'traveler',Math.min(this.travelerColumns===2?0:8,columns*rows-1)).setOrigin(.5,.96).setDisplaySize(92,92).setDepth(position.y);this.hero.walkColumns=columns;this.hero.walkRows=rows;this.guardShadow=this.add.ellipse(World.guard.x,World.guard.y,40,12,0x223e31,.25).setDepth(World.guard.y-.2);this.guard=this.add.image(World.guard.x,World.guard.y,'guard').setOrigin(.5,.98).setDisplaySize(109,109).setDepth(World.guard.y);
this.guardZone=this.add.zone(World.guard.x,World.guard.y-55,95,130).setInteractive({useHandCursor:true}).setDepth(1000);this.guardZone.on('pointerdown',(_p,_x,_y,event)=>{event.stopPropagation();this.goTalk()});this.nameTag=this.add.text(position.x,position.y-96,'Viajero',{fontFamily:'Georgia',fontSize:'17px',color:'#fff8dd',stroke:'#273b2f',strokeThickness:4}).setOrigin(.5,1).setDepth(1100);this.guardLabel=this.add.text(World.guard.x,World.guard.y-114,'Elara',{fontFamily:'Georgia',fontSize:'17px',color:'#fff4c9',stroke:'#283d30',strokeThickness:4}).setOrigin(.5,1).setDepth(1100);this.cues=window.CenizasInteractionCues.create(this);this.nameTag.setVisible(false);
this.cameras.main.setBounds(0,0,1536,1024);this.resize(this.scale.gameSize);this.cameras.main.startFollow(this.hero,true,.08,.08);this.cameras.main.centerOn(this.hero.x,this.hero.y);this.scale.on('resize',this.resize,this);this.keys=this.input.keyboard.addKeys('W,A,S,D,UP,DOWN,LEFT,RIGHT,E,C,J');this.input.keyboard.on('keydown',e=>{if(modalOpen()||e.repeat)return;if(e.code==='KeyE')this.goTalk();if(e.code==='KeyC')openModal('sheet-modal');if(e.code==='KeyJ')openModal('journal-modal')});this.time.addEvent({delay:3000,loop:true,callback:save});refreshCharacter();quest();$('loading').classList.add('hidden');this.ready=true;
// Soft mote animation uses simple particles; scenery and characters are raster assets.
for(let i=0;i<12;i++){const x=200+Math.random()*1200,y=360+Math.random()*240,dot=this.add.circle(x,y,1.4,0xffefb4,.5).setDepth(1050);this.tweens.add({targets:dot,y:y-45,alpha:0,duration:3000+Math.random()*2500,repeat:-1,delay:Math.random()*3000})}}
resize(size){stick.reset();const zoom=Math.max(.62,Math.min(1.35,Math.max(size.width/1536,size.height/1024)));this.cameras.main.setZoom(zoom)}
stop(){stick.reset();this.route=[];this.pending=null;if(this.hero){this.hero.anims.stop();window.CenizasLocomotion.frame(this.hero,0,0)}if(this.marker)this.marker.setVisible(false);if(this.keys)Object.values(this.keys).forEach(k=>k.reset())}
walkTo(target,pending=null){if(!this.ready||modalOpen())return;const end=World.nearest(target.x,target.y,80);if(!end){toast('Sigue el camino de piedra. El río y las casas no son transitables.');return}this.route=World.path(this.hero,end);this.pending=pending;this.marker.setPosition(end.x,end.y).setVisible(this.route.length>0);if(!this.route.length&&Math.hypot(this.hero.x-end.x,this.hero.y-end.y)<25)this.arrived()}
goTalk(){if(!this.ready||modalOpen())return;if(Math.hypot(this.hero.x-World.guard.x,this.hero.y-World.guard.y)<105){dialogue(stage>=2?5:0);return}toast('Te acercas a Elara…');this.walkTo(World.talkSpot,'talk')}
goGate(){if(!this.ready||modalOpen())return;if(stage<2){toast('Habla con Elara antes de entrar.');return}this.walkTo(World.gate,'gate')}
arrived(){this.marker.setVisible(false);const pending=this.pending;this.pending=null;save();if(pending==='talk')dialogue(stage>=2?5:0);if(pending==='gate'){entranceButton();toast('Estás en la puerta. Pulsa Entrar para pasar a Valdara.')}}
complete(){if(!nearEntrance())return;stage=3;quest();save();location.href='chapter.html'}
update(_time,delta){if(!this.ready||modalOpen()){this.cues?.hide();this.guardLabel?.setVisible(false);return;}this.guardLabel.setVisible(true);this.cues.draw(this.time.now,stage>=2&&stage<3?[{id:'gate',x:World.gate.x,y:World.gate.y-45}]:[]);const k=this.keys;let dx=(k.D.isDown||k.RIGHT.isDown?1:0)-(k.A.isDown||k.LEFT.isDown?1:0),dy=(k.S.isDown||k.DOWN.isDown?1:0)-(k.W.isDown||k.UP.isDown?1:0);if(!dx&&!dy){dx=stick.state.x;dy=stick.state.y}else{const length=Math.hypot(dx,dy);dx/=length;dy/=length}const oldX=this.hero.x,oldY=this.hero.y;const speed=155*Math.min(delta,40)/1000;let moving=false;if(dx||dy){this.route=[];this.pending=null;this.marker.setVisible(false);dx*=speed;dy*=speed;const next=window.CenizasNavigation.slide(World.walkable,{x:this.hero.x,y:this.hero.y},dx,dy);moving=Math.hypot(next.x-this.hero.x,next.y-this.hero.y)>.001;this.hero.setPosition(next.x,next.y);}else if(this.route.length){const p=this.route[0];dx=p.x-this.hero.x;dy=p.y-this.hero.y;const d=Math.hypot(dx,dy);if(d<=speed){this.hero.setPosition(p.x,p.y);this.route.shift();if(!this.route.length)this.arrived()}else{this.hero.x+=dx/d*speed;this.hero.y+=dy/d*speed}moving=true}if(moving&&!modalOpen()){window.CenizasLocomotion.frame(this.hero,this.hero.x-oldX,this.hero.y-oldY,delta)}else{this.hero.anims.stop();window.CenizasLocomotion.frame(this.hero,0,0,delta)}this.hero.setDepth(this.hero.y);this.playerShadow.setPosition(this.hero.x,this.hero.y).setDepth(this.hero.y-.1);this.nameTag.setPosition(this.hero.x,this.hero.y-94);this.heroVisual?.setPosition(this.hero.x,this.hero.y).setDepth(this.hero.y+.4);const heroScale=heroRaceDesigns[character?.race]?.scale||1;this.heroBadge?.setPosition(this.hero.x,this.hero.y-104*heroScale).setDepth(this.hero.y+.6);entranceButton()}
}
$('continue-adventure').onclick=()=>{if(nearEntrance())scene?.complete()};$('talk').onclick=()=>scene?.goTalk();$('quest-go').onclick=()=>openModal('region-modal');$('open-sheet').onclick=()=>openModal('sheet-modal');$('journal').onclick=()=>openModal('journal-modal');$('help').onclick=()=>openModal('help-modal');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{scene?.stop();if(d.id==='sheet-modal')refreshCharacter();$('game').focus({preventScroll:true})}));$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Tu navegador no admite pantalla completa. Puedes girar el celular.')}catch{toast('No se pudo activar pantalla completa en este navegador.')}};
document.getElementById('sheet-modal').addEventListener('close',()=>{if(!characterReadyBridge())setTimeout(()=>{openModal('sheet-modal');toast('Crea tu personaje antes de continuar.')},0)});
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==$('sheet-frame').contentWindow)return;if(event.data?.type==='character-saved')refreshCharacter();if(event.data?.type==='character-saved'&&(!characterReadyBridge()||!localStorage.getItem('cenizas-character-v1'))){toast('Completa nombre, raza, clase, subclase y género antes de entrar.');return}if(event.data?.type==='character-saved'||event.data?.type==='return-to-valdara')$('sheet-modal').close()});
window.CenizasBridge={hasSave(){try{const c=JSON.parse(localStorage.getItem('cenizas-character-v1')||'null'),p=JSON.parse(localStorage.getItem(SAVE)||'null');return Boolean(characterReadyBridge(c)&&p&&Number.isInteger(p.stage))}catch{return false}},startNew(){try{localStorage.removeItem(SAVE);localStorage.removeItem('cenizas-character-v1');localStorage.removeItem('cenizas-campaign-v2')}catch{}stage=0;position={...World.start};character=null;refreshCharacter();quest();save();openModal('sheet-modal');},continueGame(){refreshCharacter();quest();if(!characterReadyBridge())openModal('sheet-modal');}};
window.addEventListener('pagehide',save);window.addEventListener('blur',()=>{scene?.stop();save()});document.addEventListener('visibilitychange',()=>{if(document.hidden){scene?.stop();save()}});refreshCharacter();quest();if(!characterReadyBridge()&&!document.getElementById('main-menu')?.dataset.active)setTimeout(()=>{openModal('sheet-modal');toast('Crea tu personaje antes de comenzar la aventura.')},180);
if(typeof Phaser==='undefined'){$('load-text').textContent='No pudimos iniciar el juego. Recarga la página para volver a intentarlo.';return}
new Phaser.Game({type:Phaser.AUTO,parent:'game',backgroundColor:'#344c41',scale:{mode:Phaser.Scale.RESIZE,width:window.innerWidth,height:window.innerHeight},render:{antialias:true,pixelArt:false,roundPixels:false},input:{activePointers:2,keyboard:{capture:[37,38,39,40]}},scene:BridgeScene,audio:{noAudio:true},fps:{target:60,forceSetTimeOut:false}});
const refreshCharacterBase=refreshCharacter;refreshCharacter=function(){refreshCharacterBase();if(character){const bonus=character.levelBonuses||{},con=character.base[2]+({Elfo:-2,Enano:2,Gnomo:2}[character.race]||0)+(Number(bonus[2])||0),hp=Math.max(1,{Guerrero:10,Pícaro:6,Mago:4}[character.class]+Math.floor((con-10)/2))+(character.feats?.includes('Dureza')?3:0)+(character.class==='Mago'?3:0);$('player-hp').textContent=`${hp} / ${hp} PG`}};refreshCharacter();
})();
